    const ui = document.getElementById('ui');
    ui.appendChild(el('div', { class: 'title' }, [
      el('div', { class: 'logo', 'data-text': 'BONEFORGE' }, ['BONEFORGE']),
      el('div', { class: 'logo-sub' }, ['PROCEDURAL STREET FIGHTING · PIER 9']),
    ]));
